import { useRef } from 'react';
import { useScroll } from 'motion/react';

/** A scroll-pinned stage (Moto-card style). The section is `length` screens
 *  tall; its stage sticks to the viewport while you scroll through it, and
 *  `children(progress)` receives a 0→1 MotionValue to drive the scene. */
export function Pinned({ id, length = 3, className = '', children }) {
  const ref = useRef(null);
  const { scrollYProgress } = useScroll({ target: ref, offset: ['start start', 'end end'] });
  return (
    <section id={id} ref={ref} className={`pin ${className}`} style={{ height: `${length * 100}svh` }} data-scene={id}>
      <div className="pin-stage">{children(scrollYProgress)}</div>
    </section>
  );
}

/** Marketing site, told as one coding agent's story. Static sections live in
 *  ./sections, scroll-driven pinned scenes in ./scenes, the intro in ./gate. */
export function LandingPage() {
  const [intro, setIntro] = useState(introPending);
  useSmoothScroll();

  // A reload starts at the top with the intro, not mid-story under it.
  useEffect(() => {
    if ('scrollRestoration' in window.history) window.history.scrollRestoration = 'manual';
    if (introPending()) window.scrollTo(0, 0);
  }, []);
  // Freeze smooth scrolling while the intro is up.
  useEffect(() => {
    if (intro) window.__lenis?.stop();
    else window.__lenis?.start();
  }, [intro]);

  return (
    <div className="lp">
      <AnimatePresence>{intro && <Gate onDone={() => setIntro(false)} />}</AnimatePresence>
      <PaperGrain opacity={0.35} />
      <Nav />
      <Altimeter />
      <main>
        <Hero />
        <Ticker />
        <Terminal />
        <Problem />
        <Journey />
        <AgentGraph />
        <Crash />
        <Detections />
        <Remedies />
        <EvidenceMock />
        <LedgerTrack />
        <Install />
        <Facts />
        <Faq />
        <Closing />
      </main>
      <Footer onReplayIntro={() => { window.scrollTo(0, 0); setIntro(true); }} />
    </div>
  );
}
